import { editProjectCoachingConfig } from '~/client';
import type { EditProjectCoachingConfigResponse, CoachingConfig } from '~/client';
import { showToastError, showToastSuccess } from '~/utils/show-toast';

export const useEditProjectCoaching = defineMutation(() => {
  const { mutateAsync, asyncStatus } = useMutation({
    mutation: (params: { data: CoachingConfig; projectId: string }): Promise<EditProjectCoachingConfigResponse> =>
      editProjectCoachingConfig({
        composable: '$fetch',
        path: { project_id: params.projectId },
        body: ref(params.data),
      }),
    onSuccess: (_, params) => {
      const queryCache = useQueryCache();
      queryCache.invalidateQueries({ key: ['project-edit-tabs-status', params.projectId] });
      queryCache.setQueryData(['project.edit.coaching', params.projectId], () => {
        return params.data;
      });
      showToastSuccess(`Project coaching configuration edited successfully`);
    },
    onError(error) {
      showToastError(error);
    },
  });

  return {
    editProjectCoachingConfig: mutateAsync,
    isEditProjectCoachingLoading: computed(() => asyncStatus.value === 'loading'),
  };
});
