<template>
  <AppLoader v-if="isLoading" subject="coaching configuration" />
  <AppError v-else-if="error" :error="error" title="Failed to load coaching configuration" />
  <AppEmpty v-else-if="!data" subject="coaching configuration" />
  <form v-else class="grid grid-cols-8 gap-6" @submit="onSubmit" @vue:mounted="onFormMounted">
    <Card class="col-span-8">
      <CardHeader>
        <CardTitle>Work Shift-End Coaching</CardTitle>
      </CardHeader>
      <CardContent>
        <ProjectEditConfigurationFieldRow
          :label="WORKSHIFT_END_TOGGLE.label"
          :description="WORKSHIFT_END_TOGGLE.description"
        >
          <FormItemWrapper :name="WORKSHIFT_END_TOGGLE.toggleId" is-no-message>
            <template #default="{ slots }">
              <Switch
                :id="WORKSHIFT_END_TOGGLE.toggleId"
                :model-value="slots.componentField.modelValue"
                @update:model-value="slots.field.onChange"
              />
            </template>
          </FormItemWrapper>
        </ProjectEditConfigurationFieldRow>
      </CardContent>
    </Card>

    <Card class="col-span-8">
      <CardHeader>
        <CardTitle>Scheduled Review Coaching</CardTitle>
      </CardHeader>
      <CardContent>
        <ProjectEditConfigurationFieldRow
          :label="SCHEDULED_REVIEW_TOGGLE.label"
          :description="SCHEDULED_REVIEW_TOGGLE.description"
        >
          <FormItemWrapper :name="SCHEDULED_REVIEW_TOGGLE.toggleId" is-no-message>
            <template #default="{ slots }">
              <Switch
                :id="SCHEDULED_REVIEW_TOGGLE.toggleId"
                :model-value="slots.componentField.modelValue"
                @update:model-value="slots.field.onChange"
              />
            </template>
          </FormItemWrapper>
        </ProjectEditConfigurationFieldRow>
      </CardContent>
    </Card>

    <Card class="col-span-8">
      <CardHeader>
        <CardTitle>Critical Alerts</CardTitle>
      </CardHeader>
      <CardContent>
        <ProjectEditConfigurationFieldRow
          label="Enable critical alerts"
          description="Master switch for all critical-threshold alerts on this project. Default off."
        >
          <FormItemWrapper name="critical_alerts_enabled" is-no-message>
            <template #default="{ slots }">
              <Switch
                id="critical_alerts_enabled"
                :model-value="slots.componentField.modelValue"
                @update:model-value="slots.field.onChange"
              />
            </template>
          </FormItemWrapper>
        </ProjectEditConfigurationFieldRow>
        <template v-if="values.critical_alerts_enabled">
          <ProjectEditConfigurationFieldRow
            v-for="rule in ALERT_RULES"
            :key="rule.toggleId"
            :label="rule.label"
            :description="rule.description"
          >
            <FormItemWrapper :name="rule.toggleId" is-no-message>
              <template #default="{ slots }">
                <Switch
                  :id="rule.toggleId"
                  :model-value="slots.componentField.modelValue"
                  @update:model-value="slots.field.onChange"
                />
              </template>
            </FormItemWrapper>
          </ProjectEditConfigurationFieldRow>
        </template>
      </CardContent>
    </Card>

    <Card class="col-span-8">
      <CardHeader>
        <CardTitle>Coaching Metrics</CardTitle>
        <CardDescription>
          Thresholds for what the LLM evaluates. These apply to both work shift-end and scheduled review coaching.
        </CardDescription>
      </CardHeader>
      <CardContent>
        <ProjectEditConfigurationFieldRow
          v-for="metric in ALL_METRICS"
          :key="metric.toggleId"
          :label="metric.label"
          :description="metric.description"
        >
          <FormItemWrapper :name="metric.toggleId" is-no-message>
            <template #default="{ slots }">
              <Switch
                :id="metric.toggleId"
                :model-value="slots.componentField.modelValue"
                @update:model-value="slots.field.onChange"
              />
            </template>
          </FormItemWrapper>
        </ProjectEditConfigurationFieldRow>
      </CardContent>
    </Card>

    <Card class="col-span-8">
      <CardContent class="flex justify-end w-full">
        <Button
          type="submit"
          :disabled="isEditProjectCoachingLoading || isEqual(data, processedDataFromForm)"
          :loading="isEditProjectCoachingLoading"
          >Save</Button
        >
      </CardContent>
    </Card>
    <NavigationGuard
      v-if="data"
      :saved-data="data"
      :changed-data="processedDataFromForm"
      title="Warning"
      description="You have some unsaved changes on this tab! Save them before switching to another tab."
      confirm-text="Discard Changes"
    />
  </form>
</template>

<script setup lang="ts">
import { useForm } from 'vee-validate';
import { formSchema } from '~/constants/validationSchemas/projectEditCoaching';
import { getCoachingConfigForProject } from '~/client';
import type { CoachingConfig, ScoreMetric, RateMetric, CountMetric } from '~/client';
import { useEditProjectCoaching } from '~/mutations/project/edit/coaching';
import { isEqual } from 'lodash';
import {
  SCORE_METRICS,
  RATE_METRICS,
  COUNT_METRICS,
  ALERT_RULES,
  COACHING_FEEDBACK_TOGGLES,
} from '~/constants/projects/canvassingProjectCoaching';

const ALL_METRICS = [...SCORE_METRICS, ...RATE_METRICS, ...COUNT_METRICS];
const WORKSHIFT_END_TOGGLE = COACHING_FEEDBACK_TOGGLES.find((t) => t.key === 'workshift_end_enabled')!;
const SCHEDULED_REVIEW_TOGGLE = COACHING_FEEDBACK_TOGGLES.find((t) => t.key === 'scheduled_review_enabled')!;

definePageMeta({
  backGroup: 'project-edit',
  roles: ['admin'],
  backLabel: 'project edit',
});

const route = useRoute('projects-id-edit-coaching');

const { data, isLoading, error } = useQuery({
  key: () => ['project.edit.coaching', route.params.id],
  query: () => getCoachingConfigForProject({ composable: '$fetch', path: { project_id: route.params.id } }),
  enabled: () => !!route.params.id,
});

const { handleSubmit, setValues, values } = useForm({
  validationSchema: formSchema,
  initialValues: {},
  // Critical-alert rule fields are conditionally rendered (v-if). Without this, unmounting
  // them strips their values, so the required Zod fields fail validation and Save silently
  // no-ops. Matches the project Configuration forms.
  keepValuesOnUnmount: true,
});

const { editProjectCoachingConfig, isEditProjectCoachingLoading } = useEditProjectCoaching();

const onSubmit = handleSubmit(async () => {
  if (!processedDataFromForm.value) return;

  await editProjectCoachingConfig({ data: processedDataFromForm.value, projectId: route.params.id });
});

function onFormMounted() {
  if (!data.value) return;
  const coaching = data.value.conversational_coaching;
  const alerts = data.value.critical_alerts;

  const formValues: Record<string, boolean> = {};

  for (const m of SCORE_METRICS) {
    formValues[m.toggleId] = coaching.score_metrics[m.key as ScoreMetric]?.enabled ?? false;
  }
  for (const m of RATE_METRICS) {
    formValues[m.toggleId] = coaching.rate_metrics[m.key as RateMetric]?.enabled ?? false;
  }
  for (const m of COUNT_METRICS) {
    formValues[m.toggleId] = coaching.count_metrics[m.key as CountMetric]?.enabled ?? false;
  }

  formValues.critical_alerts_enabled = alerts.enabled;
  formValues.workshift_end_enabled = coaching.workshift_end_enabled ?? false;
  formValues.scheduled_review_enabled = coaching.scheduled_review_enabled ?? false;
  for (const a of ALERT_RULES) {
    const rule = alerts[a.key as 'profanity_streak' | 'mismatch_streak' | 'identity_failure_streak'];
    formValues[a.toggleId] = rule?.enabled ?? false;
  }

  setValues(formValues, false);
}

const processedDataFromForm = computed<CoachingConfig | null>(() => {
  if (!data.value) return null;
  const coaching = data.value.conversational_coaching;
  const alerts = data.value.critical_alerts;

  const formValues = values as Record<string, boolean | undefined>;

  const scoreMetrics: CoachingConfig['conversational_coaching']['score_metrics'] = {};
  for (const m of SCORE_METRICS) {
    const key = m.key as ScoreMetric;
    scoreMetrics[key] = {
      enabled: formValues[m.toggleId] || false,
      value: coaching.score_metrics[key]?.value ?? {
        critical: 0,
        needs_improvement: 0,
        trend_delta_high: 0,
        trend_delta_low: 0,
      },
    };
  }

  const rateMetrics: CoachingConfig['conversational_coaching']['rate_metrics'] = {};
  for (const m of RATE_METRICS) {
    const key = m.key as RateMetric;
    rateMetrics[key] = {
      enabled: formValues[m.toggleId] || false,
      value: coaching.rate_metrics[key]?.value ?? { acceptable: 0, needs_improvement: 0, trend_delta: 0 },
    };
  }

  const countMetrics: CoachingConfig['conversational_coaching']['count_metrics'] = {};
  for (const m of COUNT_METRICS) {
    const key = m.key as CountMetric;
    countMetrics[key] = {
      enabled: formValues[m.toggleId] || false,
      value: coaching.count_metrics[key]?.value ?? { critical: 0, trend_delta: 0 },
    };
  }

  return {
    conversational_coaching: {
      workshift_end_enabled: values.workshift_end_enabled || false,
      scheduled_review_enabled: values.scheduled_review_enabled || false,
      max_profanity_words: coaching.max_profanity_words,
      max_evidence_quotes: coaching.max_evidence_quotes,
      score_metrics: scoreMetrics,
      rate_metrics: rateMetrics,
      count_metrics: countMetrics,
    },
    critical_alerts: {
      enabled: values.critical_alerts_enabled || false,
      profanity_streak: {
        enabled: values.alert_profanity_streak_enabled || false,
        value: alerts.profanity_streak.value,
      },
      mismatch_streak: {
        enabled: values.alert_mismatch_streak_enabled || false,
        value: alerts.mismatch_streak.value,
      },
      identity_failure_streak: {
        enabled: values.alert_identity_failure_streak_enabled || false,
        value: alerts.identity_failure_streak.value,
      },
    },
  };
});
</script>
